package app.xiaohe.tests;

import android.content.*;
import android.database.Cursor;
import android.database.DatabaseErrorHandler;
import android.database.sqlite.SQLiteDatabase;
import app.xiaohe.assistant.*;
import org.json.*;
import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.time.*;
import java.util.*;

/** Dedicated-test-AVD only. Uses isolated SQLite and empty fixture preferences, never real keys. */
public final class ScheduleApiSmoke {
  private static final String ZONE="America/Los_Angeles";
  private static final long BASE=OffsetDateTime.parse("2033-03-28T23:45:00-07:00").toInstant().toEpochMilli();
  private static void ok(boolean value,String why){if(!value)throw new AssertionError(why);}
  private static String id(){return UUID.randomUUID().toString();}
  private static long at(String value){return OffsetDateTime.parse(value).toInstant().toEpochMilli();}
  private static final class FixtureContext extends ContextWrapper {
    final File root;final String prefix;
    FixtureContext(Context base)throws Exception {super(base);prefix="schedule-api-fixture-"+id();root=new File(base.getCacheDir(),prefix);if(!root.mkdirs())throw new IOException("Cannot create isolated fixture");}
    @Override public Context getApplicationContext(){return this;}
    private File dir(String name){File f=new File(root,name);f.mkdirs();return f;}
    @Override public File getCacheDir(){return dir("cache");}
    @Override public File getFilesDir(){return dir("files");}
    @Override public File getDatabasePath(String name){return new File(dir("databases"),name);}
    @Override public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory){return SQLiteDatabase.openOrCreateDatabase(getDatabasePath(name).getPath(),factory);}
    @Override public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory,DatabaseErrorHandler handler){return SQLiteDatabase.openOrCreateDatabase(getDatabasePath(name).getPath(),factory,handler);}
    @Override public boolean deleteDatabase(String name){return SQLiteDatabase.deleteDatabase(getDatabasePath(name));}
    @Override public SharedPreferences getSharedPreferences(String name,int mode){return getBaseContext().getSharedPreferences(prefix+"-"+name,mode);}
  }
  private static JSONObject message(Store db,String text,long time,String zone,JSONArray files)throws Exception {JSONObject m=new JSONObject().put("id",id()).put("role","user").put("content",text).put("files",files).put("created",time).put("capturedAt",time).put("capturedZone",zone).put("contextMessageIds",new JSONArray());db.put("messages",m);return m;}
  private static JSONObject memory(Store db,JSONObject source,String title,String kind,String type,String status,String event,long start)throws Exception {JSONObject r=new JSONObject().put("id",id()).put("created",source.getLong("created")).put("sourceId",source.getString("id")).put("sourceAnchor",TimeAnchor.source(source)).put("title",title).put("content",title).put("kind",kind).put("type",type).put("status",status).put("truthState","current").put("eventState",event).put("files",new JSONArray()).put("tags",new JSONArray().put("咖啡资料"));if(start>0)r.put("time",new JSONObject().put("state","resolved").put("start",start).put("end",start+3600000).put("precision","minute").put("raw","明确日期").put("source","user"));else r.put("time",new JSONObject().put("state","unscheduled").put("raw","改天").put("source","user"));db.put("memories",r);return r;}
  private static int count(Store db){try(Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM memories",null)){c.moveToFirst();return c.getInt(0);}}
  private static Set<String> ids(JSONArray values){Set<String> out=new HashSet<>();for(int i=0;i<values.length();i++)out.add(values.optString(i));return out;}
  private static void local(JSONObject answer,String expectedDate,Set<String> expected)throws Exception {ok(answer.optBoolean("local"),"Calendar question must bypass the model");ok(answer.getString("intent").equals("query")&&answer.getJSONArray("memories").length()==0,"A calendar question cannot become an arrangement");ok(answer.getJSONObject("queryTime").getString("date").equals(expectedDate),"Tomorrow must use the original local calendar");ok(ids(answer.getJSONArray("evidenceIds")).equals(expected),"Local answer must cite the actual valid schedules");ok(answer.getJSONArray("reminderEligibleIds").length()==0,"Querying an arrangement cannot start reminders");}
  private static JSONObject reply(AiEngine engine,JSONObject source,String intent,String text)throws Exception {JSONObject ai=new JSONObject().put("intent",intent).put("reply",text).put("updates",new JSONArray());Method reconcile=AiEngine.class.getDeclaredMethod("reconcileReply",JSONObject.class,JSONObject.class);reconcile.setAccessible(true);reconcile.invoke(engine,source,ai);return ai;}
  private static void dateReplies(Store db,Context context)throws Exception {
    AiEngine engine=new AiEngine(context);JSONObject source=message(db,"明天去医院",BASE,ZONE,new JSONArray());AbsoluteDates.capture(source);JSONObject saved=memory(db,source,"明天去医院fixture","event","event","active","planned",at("2033-03-29T09:00:00-07:00"));saved.getJSONObject("time").put("raw","明天");db.put("memories",saved);source.put("memoryIds",new JSONArray().put(saved.getString("id")));db.put("messages",source);
    JSONObject answer=reply(engine,source,"record","记着，明天去医院。");ok(answer.getString("reply").contains("2033年3月29日")&&!answer.getString("reply").contains("明天"),"A saved record acknowledgement must give the date fixed at capture");ok(answer.getJSONObject("helper_summary").getString("plannedTimeRaw").contains("2033年3月29日"),"The fallback acknowledgement must use the saved absolute date");ok(reply(engine,source,"record","").getString("reply").contains("2033年3月29日"),"An empty model acknowledgement cannot leave a relative date in the fallback");ok(db.one("messages",source.getString("id")).getString("content").equals("明天去医院"),"Reply date normalization must preserve the user's original utterance");
    source.put("capturedAt",BASE+86400000L).put("capturedZone","Asia/Shanghai");ok(reply(engine,source,"record","明天去医院。").getString("reply").contains("2033年3月29日"),"A retry must use frozen date mappings despite a changed processing clock or zone");ok(reply(engine,source,"record","今天先记着，明天去医院，后天再说。").getString("reply").equals("今天先记着，2033年3月29日去医院，后天再说。"),"Only relative date words present in the original verified user input may be normalized");
    JSONObject update=message(db,"后天去医院",BASE,ZONE,new JSONArray());AbsoluteDates.capture(update);ok(reply(engine,update,"update","后天去医院的更改记好了。").getString("reply").contains("2033年3月30日"),"Update acknowledgements must use the update source's captured date");ok(reply(engine,source,"query","明天的安排我查过了。").getString("reply").equals("明天的安排我查过了。"),"Queries retain their own date-answer path");
    JSONObject external=message(db,"截图里写着明天去医院",BASE,ZONE,new JSONArray());AbsoluteDates.capture(external);ok(reply(engine,external,"record","截图里写着明天去医院。").getString("reply").equals("截图里写着明天去医院。"),"An unknown attachment-author date cannot become the user's capture date");ok(reply(engine,source,"record","上次说的明天先保留，明天去医院。").getString("reply").equals("上次说的明天先保留，2033年3月29日去医院。"),"Historical references and new user dates must keep their separate anchors");
  }
  private static void cleanup(File root,File file)throws Exception {File r=root.getCanonicalFile(),f=file.getCanonicalFile();if(!f.equals(r)&&!f.toPath().startsWith(r.toPath()))throw new IOException("Fixture cleanup escaped its own root");if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)for(File child:children)cleanup(r,child);}f.delete();}
  public static void run(Context base)throws Exception {run(base,"http://10.0.2.2:8902/v1");}
  public static void run(Context base,String apiBase)throws Exception {
    FixtureContext context=new FixtureContext(base);Field singleton=Store.class.getDeclaredField("instance");singleton.setAccessible(true);Object previous=singleton.get(null);Store db=null;
    try {
      singleton.set(null,null);db=Store.get(context);Settings settings=new Settings(context);ok(!settings.connected(),"Fixture preferences must begin empty without reading personal settings");
      JSONObject seed=message(db,"隔离日程资料",BASE-3600000,ZONE,new JSONArray());long tomorrow=at("2033-03-29T09:00:00-07:00");JSONObject dentist=memory(db,seed,"牙科复诊fixture","event","event","active","planned",tomorrow),dinner=memory(db,seed,"和朋友吃饭fixture","intent","task","active","planned",at("2033-03-29T19:00:00-07:00"));Set<String> expected=new HashSet<>(Arrays.asList(dentist.getString("id"),dinner.getString("id")));
      memory(db,seed,"已经完成fixture","intent","task","completed","planned",tomorrow);memory(db,seed,"旧的归档fixture","intent","task","archived","planned",tomorrow);memory(db,seed,"已发生的旧事件fixture","event","event","active","occurred",tomorrow);JSONObject canceled=memory(db,seed,"取消的预约fixture","event","event","active","planned",tomorrow);canceled.put("canceled",true);db.put("memories",canceled);memory(db,seed,"时间先不定fixture","intent","task","active","planned",0);
      int before=count(db);JSONObject query=message(db,"我明天有什么安排",BASE,ZONE,new JSONArray());JSONObject answer=new AiEngine(context).process(query,null);local(answer,"2033-03-29",expected);ok(count(db)==before&&db.one("messages",query.getString("id")).getJSONArray("memoryIds").length()==0,"An offline query cannot create a saved task");ok(answer.getString("reply").contains("2033年3月29日")&&answer.getString("reply").contains("\n1."),"The local answer must preserve its explicit date and multi-line list");
      local(new AiEngine(context).process(query,null),"2033-03-29",expected);ok(count(db)==before,"Retrying a question cannot create duplicate arrangements");JSONObject legacy=message(db,"我明天有什么安排",BASE,ZONE,new JSONArray());legacy.remove("capturedAt");db.put("messages",legacy);local(new AiEngine(context).process(legacy,null),"2033-03-29",expected);
      JSONObject china=message(db,"我明天有什么安排",BASE,"Asia/Shanghai",new JSONArray());local(new AiEngine(context).process(china,null),"2033-03-30",expected);ok(new AiEngine(context).process(message(db,"后天有什么安排",BASE,ZONE,new JSONArray()),null).getJSONArray("evidenceIds").length()==0,"A nearby empty date cannot reuse tomorrow's schedules");
      String voiceId=id();File voice=db.filePath(voiceId);try(OutputStream out=new FileOutputStream(voice)){out.write(0);}db.put("files",new JSONObject().put("id",voiceId).put("created",BASE).put("name","fixture.m4a").put("mime","audio/mp4").put("recorded",true).put("text","我明天有什么安排").put("size",voice.length()).put("sha256",MediaProcessor.hash(voice)));JSONObject spoken=message(db,"我明天有什么安排",BASE,ZONE,new JSONArray().put(voiceId));spoken.put("voiceText","我明天有什么安排");db.put("messages",spoken);local(new AiEngine(context).process(spoken,null),"2033-03-29",expected);ok(db.one("messages",spoken.getString("id")).getJSONArray("files").optString(0).equals(voiceId),"A local voice query must retain its original audio reference");
      settings.save(new JSONObject().put("baseUrl","http://127.0.0.1:1/v1").put("model","offline-never-call"));local(new AiEngine(context).process(message(db,"我明天有什么安排",BASE,ZONE,new JSONArray()),null),"2033-03-29",expected);
      boolean rejected=false;try{new AiEngine(context).process(message(db,"明天去医院",BASE,ZONE,new JSONArray()),null);}catch(Exception expectedFailure){rejected=true;}ok(rejected,"A recording request cannot be swallowed by the local calendar overview");
      JSONObject inRange=memory(db,seed,"咖啡资料：日期范围内fixture","note","learning","active","",at("2033-03-29T10:00:00-07:00"));memory(db,seed,"咖啡资料：日期范围外fixture","note","learning","active","",at("2033-03-28T10:00:00-07:00"));memory(db,seed,"咖啡资料：没有日期fixture","note","learning","active","",0);
      JSONObject knownClock=new JSONObject().put("id",id()).put("kind","intent").put("type","task").put("time",new JSONObject().put("state","ambiguous_clock").put("dateStart",at("2033-03-29T00:00:00-07:00")).put("needsMeridiem",true).put("candidateHour",8).put("raw","明天8点").put("anchor",TimeAnchor.source(seed)));JSONObject datedQuestion=new JSONObject().put("content","明天的咖啡资料有哪些？").put("created",BASE).put("capturedAt",BASE).put("capturedZone",ZONE);Method filter=AiEngine.class.getDeclaredMethod("dateCandidates",JSONArray.class,JSONObject.class,String.class);filter.setAccessible(true);JSONArray retained=(JSONArray)filter.invoke(new AiEngine(context),new JSONArray().put(knownClock),ScheduleQuery.range(datedQuestion),datedQuestion.getString("content"));ok(retained.length()==1&&retained.getJSONObject(0).getString("queryTimeBasis").equals("date_known"),"The API keeps an explicit date when an AM/PM clock remains unknown");ok(knownClock.getJSONObject("time").getString("state").equals("ambiguous_clock")&&knownClock.optLong("remindAt")==0,"A query projection cannot turn an unknown clock into a saved reminder");
      settings.save(new JSONObject().put("baseUrl",apiBase).put("model","schedule-date-fixture").put("vision",false));JSONObject apiQuery=message(db,"明天的咖啡资料有哪些？",BASE,ZONE,new JSONArray());apiQuery.put("contextMessageIds",new JSONArray().put(seed.getString("id")));db.put("messages",apiQuery);before=count(db);JSONObject apiAnswer=new AiEngine(context).process(apiQuery,null);ok(!apiAnswer.optBoolean("local")&&apiAnswer.getString("intent").equals("query"),"Specific material queries must still reach the API");ok(apiAnswer.getJSONObject("queryTime").getString("date").equals("2033-03-29")&&apiAnswer.getJSONObject("queryTime").getString("zone").equals(ZONE),"API answers must retain the original query range");ok(ids(apiAnswer.getJSONArray("evidenceIds")).equals(new HashSet<>(Arrays.asList(inRange.getString("id"))))&&count(db)==before,"Only the exact dated evidence is cited and no question is stored as a task");
      JSONObject retried=new AiEngine(context).process(apiQuery,null);ok(retried.getJSONObject("queryTime").getString("date").equals("2033-03-29")&&count(db)==before,"An API retry cannot replace the original date with today's device date");dateReplies(db,context);
    }finally{singleton.set(null,previous);if(db!=null)db.close();base.deleteSharedPreferences(context.prefix+"-settings");base.deleteSharedPreferences(context.prefix+"-maintenance");cleanup(context.root,context.root);}
  }
}
